insert into public.legislacao_artigos (referencia, texto, vigencia_de, id_materia, id_topico) values

-- -----------------------------------------------------------------------------
-- DIREITO CONSTITUCIONAL (ID 15) — TÓPICO 76: Direitos Fundamentais / Nacionalidade e Direitos Políticos
-- -----------------------------------------------------------------------------
('CF/88 — art. 12 (caput)', 'São brasileiros: I - natos: a) os nascidos na República Federativa do Brasil, ainda que de pais estrangeiros, desde que estes não estejam a serviço de seu país; b) os nascidos no estrangeiro, de pai brasileiro ou mãe brasileira, desde que qualquer deles esteja a serviço da República Federativa do Brasil; c) os nascidos no estrangeiro de pai brasileiro ou de mãe brasileira, desde que sejam registrados em repartição brasileira competente ou venham a residir na República Federativa do Brasil e optem, em qualquer tempo, depois de atingida a maioridade, pela nacionalidade brasileira; II - naturalizados: a) os que, na forma da lei, adquiram a nacionalidade brasileira, exigidas aos originários de países de língua portuguesa apenas residência por um ano ininterrupto e idoneidade moral; b) os estrangeiros de qualquer nacionalidade, residentes na República Federativa do Brasil há mais de quinze anos ininterruptos e sem condenação penal, desde que requeiram a nacionalidade brasileira.', '1988-10-05', 15, 76),
('CF/88 — art. 12, § 3º', 'São privativos de brasileiro nato os cargos: I - de Presidente e Vice-Presidente da República; II - de Presidente da Câmara dos Deputados; III - de Presidente do Senado Federal; IV - de Ministro do Supremo Tribunal Federal; V - da carreira diplomática; VI - de oficial das Forças Armadas; VII - de Ministro de Estado da Defesa.', '1988-10-05', 15, 76),
('CF/88 — art. 12, § 4º', 'Será declarada a perda da nacionalidade do brasileiro que: I - tiver cancelada sua naturalização, por sentença judicial, em virtude de fraude relacionada ao processo de naturalização ou de atentado contra a ordem constitucional e o Estado Democrático; II - fizer pedido expresso de perda da nacionalidade brasileira perante autoridade brasileira competente, ressalvadas situações que acarretem apatridia. (Redação dada pela Emenda Constitucional nº 131, de 2023)', '2023-10-03', 15, 76),
('CF/88 — art. 14 (caput)', 'A soberania popular será exercida pelo sufrágio universal e pelo voto direto e secreto, com valor igual para todos, e, nos termos da lei, mediante: I - plebiscito; II - referendo; III - iniciativa popular.', '1988-10-05', 15, 76),
('CF/88 — art. 14, § 1º', 'O alistamento eleitoral e o voto são: I - obrigatórios para os maiores de dezoito anos; II - facultativos para: a) os analfabetos; b) os maiores de setenta anos; c) os maiores de dezesseis e menores de dezoito anos.', '1988-10-05', 15, 76),
('CF/88 — art. 14, § 3º', 'São condições de elegibilidade, na forma da lei: I - a nacionalidade brasileira; II - o pleno exercício dos direitos políticos; III - o alistamento eleitoral; IV - o domicílio eleitoral na circunscrição; V - a filiação partidária; VI - a idade mínima de: a) trinta e cinco anos para Presidente e Vice-Presidente da República e Senador; b) trinta anos para Governador e Vice-Governador de Estado e do Distrito Federal; c) vinte e um anos para Deputado Federal, Deputado Estadual ou Distrital, Prefeito, Vice-Prefeito e juiz de paz; d) dezoito anos para Vereador.', '1988-10-05', 15, 76),
('CF/88 — art. 15', 'É vedada a cassação de direitos políticos, cuja perda ou suspensão só se dará nos casos de: I - cancelamento da naturalização por sentença transitada em julgado; II - incapacidade civil absoluta; III - condenação criminal transitada em julgado, enquanto durarem seus efeitos; IV - recusa de cumprir obrigação a todos imposta ou prestação alternativa, nos termos do art. 5º, VIII; V - improbidade administrativa, nos termos do art. 37, § 4º.', '1988-10-05', 15, 76),

-- -----------------------------------------------------------------------------
-- DIREITO CONSTITUCIONAL (ID 15) — TÓPICO 163: Organização do Estado e Repartição de Competências
-- -----------------------------------------------------------------------------
('CF/88 — art. 18 (caput)', 'A organização político-administrativa da República Federativa do Brasil compreende a União, os Estados, o Distrito Federal e os Municípios, todos autônomos, nos termos desta Constituição.', '1988-10-05', 15, 163),
('CF/88 — art. 21', 'Compete à União: I - manter relações com Estados estrangeiros e participar de organizações internacionais; II - declarar a guerra e celebrar a paz; III - assegurar a defesa nacional; IV - permitir, nos casos previstos em lei complementar, que forças estrangeiras transitem pelo território nacional ou nele permaneçam temporariamente; V - decretar o estado de sítio, o estado de defesa e a intervenção federal; VI - emitir moeda; VII - administrar as reservas cambiais do País e fiscalizar as operações de natureza financeira; XIV - organizar e manter a polícia civil, a polícia penal, a polícia militar e o corpo de bombeiros militar do Distrito Federal, bem como prestar assistência financeira ao Distrito Federal para a execução de serviços públicos, por meio de fundo próprio.', '1988-10-05', 15, 163),
('CF/88 — art. 22', 'Compete privativamente à União legislar sobre: I - direito civil, comercial, penal, processual, eleitoral, agrário, marítimo, aeronáutico, espacial e do trabalho; II - desapropriação; III - requisições civis e militares, em caso de iminente perigo e em tempo de guerra; IV - águas, energia, informática, telecomunicações e radiodifusão; VI - sistema monetário e de medidas, títulos e garantias dos metais; VII - política de crédito, câmbio, seguros e transferência de valores; XI - trânsito e transporte; XXII - competência da polícia federal e das polícias rodoviária e ferroviária federais; XXVII - normas gerais de licitação e contratação, em todas as modalidades, para as administrações públicas diretas, autárquicas e fundacionais da União, Estados, Distrito Federal e Municípios. Parágrafo único. Lei complementar poderá autorizar os Estados a legislar sobre questões específicas das matérias relacionadas neste artigo.', '1988-10-05', 15, 163),
('CF/88 — art. 23', 'É competência comum da União, dos Estados, do Distrito Federal e dos Municípios: I - zelar pela guarda da Constituição, das leis e das instituições democráticas e conservar o patrimônio público; II - cuidar da saúde e assistência pública, da proteção e garantia das pessoas portadoras de deficiência; III - proteger os documentos, as obras e outros bens de valor histórico, artístico e cultural, os monumentos, as paisagens naturais notáveis e os sítios arqueológicos; VI - proteger o meio ambiente e combater a poluição em qualquer de suas formas.', '1988-10-05', 15, 163),
('CF/88 — art. 24', 'Compete à União, aos Estados e ao Distrito Federal legislar concorrentemente sobre: I - direito tributário, financeiro, penitenciário, econômico e urbanístico; II - orçamento; V - produção e consumo; VIII - responsabilidade por dano ao meio ambiente, ao consumidor, a bens e direitos de valor artístico, estético, histórico, turístico e paisagístico. § 1º No âmbito da legislação concorrente, a competência da União limitar-se-á a estabelecer normas gerais. § 2º A competência da União para legislar sobre normas gerais não exclui a competência suplementar dos Estados. § 3º Inexistindo lei federal sobre normas gerais, os Estados exercerão a competência legislativa plena, para atender a suas peculiaridades. § 4º A superveniência de lei federal sobre normas gerais suspende a eficácia da lei estadual, no que lhe for contrário.', '1988-10-05', 15, 163),
('CF/88 — art. 30', 'Compete aos Municípios: I - legislar sobre assuntos de interesse local; II - suplementar a legislação federal e a estadual no que couber; III - instituir e arrecadar os tributos de sua competência, bem como aplicar suas rendas; V - organizar e prestar, diretamente ou sob regime de concessão ou permissão, os serviços públicos de interesse local, incluído o de transporte coletivo, que tem caráter essencial.', '1988-10-05', 15, 163),

-- -----------------------------------------------------------------------------
-- DIREITO CONSTITUCIONAL (ID 15) — TÓPICO 498: Processo Legislativo e Cláusulas Pétreas
-- -----------------------------------------------------------------------------
('CF/88 — art. 59', 'O processo legislativo compreende a elaboração de: I - emendas à Constituição; II - leis complementares; III - leis ordinárias; IV - leis delegadas; V - medidas provisórias; VI - decretos legislativos; VII - resoluções.', '1988-10-05', 15, 498),
('CF/88 — art. 60 (caput)', 'A Constituição poderá ser emendada mediante proposta: I - de um terço, no mínimo, dos membros da Câmara dos Deputados ou do Senado Federal; II - do Presidente da República; III - de mais da metade das Assembléias Legislativas das unidades da Federação, manifestando-se, cada uma delas, pela maioria relativa de seus membros.', '1988-10-05', 15, 498),
('CF/88 — art. 60, § 1º', 'A Constituição não poderá ser emendada na vigência de intervenção federal, de estado de defesa ou de estado de sítio.', '1988-10-05', 15, 498),
('CF/88 — art. 60, § 2º', 'A proposta será discutida e votada em cada Casa do Congresso Nacional, em dois turnos, considerando-se aprovada se obtiver, em ambos, três quintos dos votos dos respectivos membros.', '1988-10-05', 15, 498),
('CF/88 — art. 60, § 4º', 'Não será objeto de deliberação a proposta de emenda tendente a abolir: I - a forma federativa de Estado; II - o voto direto, secreto, universal e periódico; III - a separação dos Poderes; IV - os direitos e garantias individuais (cláusulas pétreas).', '1988-10-05', 15, 498),
('CF/88 — art. 62 (caput)', 'Em caso de relevância e urgência, o Presidente da República poderá adotar medidas provisórias, com força de lei, devendo submetê-las de imediato ao Congresso Nacional.', '2001-09-11', 15, 498),
('CF/88 — art. 62, § 1º', 'É vedada a edição de medidas provisórias sobre matéria: I - relativa a: a) nacionalidade, cidadania, direitos políticos, partidos políticos e direito eleitoral; b) direito penal, processual penal e processual civil; c) organização do Poder Judiciário e do Ministério Público, a carreira e a garantia de seus membros; d) planos plurianuais, diretrizes orçamentárias, orçamento e créditos adicionais e suplementares, ressalvado o previsto no art. 167, § 3º; II - que vise a detenção ou seqüestro de bens, de poupança popular ou qualquer outro ativo financeiro; III - reservada a lei complementar; IV - já disciplinada em projeto de lei aprovado pelo Congresso Nacional e pendente de sanção ou veto do Presidente da República.', '2001-09-11', 15, 498),

-- -----------------------------------------------------------------------------
-- DIREITO CONSTITUCIONAL (ID 15) — TÓPICO 501: Poder Executivo e Atribuições
-- -----------------------------------------------------------------------------
('CF/88 — art. 84 (caput)', 'Compete privativamente ao Presidente da República: I - nomear e exonerar os Ministros de Estado; II - exercer, com o auxílio dos Ministros de Estado, a direção superior da administração federal; IV - sancionar, promulgar e fazer publicar as leis, bem como expedir decretos e regulamentos para sua fiel execução; VI - dispor, mediante decreto, sobre: a) organização e funcionamento da administração federal, quando não implicar aumento de despesa nem criação ou extinção de órgãos públicos; b) extinção de funções ou cargos públicos, quando vagos; VII - manter relações com Estados estrangeiros e acreditar seus representantes diplomáticos; XII - conceder indulto e comutar penas, com audiência, se necessário, dos órgãos instituídos em lei; XIII - exercer o comando supremo das Forças Armadas. Parágrafo único. O Presidente da República poderá delegar as atribuições mencionadas nos incisos VI, XII e XIII, primeira parte, aos Ministros de Estado, ao Procurador-Geral da República ou ao Advogado-Geral da União, que observarão os limites traçados nas respectivas delegações.', '1988-10-05', 15, 501),
('CF/88 — art. 85', 'São crimes de responsabilidade os atos do Presidente da República que atentem contra a Constituição Federal e, especialmente, contra: I - a existência da União; II - o livre exercício do Poder Legislativo, do Poder Judiciário, do Ministério Público e dos Poderes constitucionais das unidades da Federação; III - o exercício dos direitos políticos, individuais e sociais; IV - a segurança interna do País; V - a probidade na administração; VI - a lei orçamentária; VII - o cumprimento das leis e das decisões judiciais.', '1988-10-05', 15, 501),

-- -----------------------------------------------------------------------------
-- DIREITO CONSTITUCIONAL (ID 15) — TÓPICO 75: Poder Judiciário (STF e STJ)
-- -----------------------------------------------------------------------------
('CF/88 — art. 102, I', 'Compete ao Supremo Tribunal Federal, precipuamente, a guarda da Constituição, cabendo-lhe: I - processar e julgar, originariamente: a) a ação direta de inconstitucionalidade de lei ou ato normativo federal ou estadual e a ação declaratória de constitucionalidade de lei ou ato normativo federal; b) nas infrações penais comuns, o Presidente da República, o Vice-Presidente, os membros do Congresso Nacional, seus próprios Ministros e o Procurador-Geral da República; c) nas infrações penais comuns e nos crimes de responsabilidade, os Ministros de Estado e os Comandantes da Marinha, do Exército e da Aeronáutica, ressalvado o disposto no art. 52, I, os membros dos Tribunais Superiores, os do Tribunal de Contas da União e os chefes de missão diplomática de caráter permanente; d) o habeas corpus, sendo paciente qualquer das pessoas referidas nas alíneas anteriores; o mandado de segurança e o habeas data contra atos do Presidente da República, das Mesas da Câmara e do Senado Federal, do Tribunal de Contas da União, do Procurador-Geral da República e do próprio Supremo Tribunal Federal;', '1988-10-05', 15, 75),
('CF/88 — art. 102, III', 'Compete ao Supremo Tribunal Federal julgar, mediante recurso extraordinário, as causas decididas em única ou última instância, quando a decisão recorrida: a) contrariar dispositivo desta Constituição; b) declarar a inconstitucionalidade de tratado ou lei federal; c) julgar válida lei ou ato de governo local contestado em face desta Constituição; d) julgar válida lei local contestada em face de lei federal. § 3º No recurso extraordinário o recorrente deverá demonstrar a repercussão geral das questões constitucionais discutidas no caso.', '1988-10-05', 15, 75),
('CF/88 — art. 105, I', 'Compete ao Superior Tribunal de Justiça: I - processar e julgar, originariamente: a) nos crimes comuns, os Governadores dos Estados e do Distrito Federal, e, nestes e nos de responsabilidade, os desembargadores dos Tribunais de Justiça dos Estados e do Distrito Federal, os membros dos Tribunais de Contas dos Estados e do Distrito Federal, os dos Tribunais Regionais Federais, dos Tribunais Regionais Eleitorais e do Trabalho, os membros dos Conselhos ou Tribunais de Contas dos Municípios e os do Ministério Público da União que oficiem perante tribunais; b) os mandados de segurança e os habeas data contra ato de Ministro de Estado, dos Comandantes da Marinha, do Exército e da Aeronáutica ou do próprio Tribunal;', '1988-10-05', 15, 75),
('CF/88 — art. 105, III', 'Compete ao Superior Tribunal de Justiça julgar, em recurso especial, as causas decididas, em única ou última instância, pelos Tribunais Regionais Federais ou pelos tribunais dos Estados, do Distrito Federal e Territórios, quando a decisão recorrida: a) contrariar tratado ou lei federal, ou negar-lhes vigência; b) julgar válido ato de governo local contestado em face de lei federal; c) der a lei federal interpretação divergente da que lhe haja atribuído outro tribunal.', '1988-10-05', 15, 75),

-- -----------------------------------------------------------------------------
-- DIREITO ADMINISTRATIVO (ID 14) — TÓPICO 492: Lei Anticorrupção (Lei nº 12.846/2013)
-- -----------------------------------------------------------------------------
('Lei nº 12.846/2013 — art. 1º (caput)', 'Esta Lei dispõe sobre a responsabilização administrativa e civil de pessoas jurídicas pela prática de atos contra a administração pública, nacional ou estrangeira. Parágrafo único. Aplica-se o disposto nesta Lei às sociedades empresárias e às sociedades simples, personificadas ou não, independentemente da forma de organização ou do modelo societário adotado, bem como a quaisquer fundações, associações de entidades ou pessoas, ou sociedades estrangeiras, que tenham sede, filial ou representação no território brasileiro, constituídas de fato ou de direito, ainda que temporariamente.', '2013-08-01', 14, 492),
('Lei nº 12.846/2013 — art. 2º', 'As pessoas jurídicas serão responsabilizadas objetivamente, nos âmbitos administrativo e civil, pelos atos lesivos previstos nesta Lei praticados em seu interesse ou benefício, exclusivo ou não.', '2013-08-01', 14, 492),
('Lei nº 12.846/2013 — art. 5º', 'Constituem atos lesivos à administração pública, nacional ou estrangeira, para os fins desta Lei, todos aqueles praticados pelas pessoas jurídicas mencionadas no parágrafo único do art. 1º, que atentem contra o patrimônio público nacional ou estrangeiro, contra princípios da administração pública ou contra os compromissos internacionais assumidos pelo Brasil, assim definidos: I - prometer, oferecer ou dar, direta ou indiretamente, vantagem indevida a agente público, ou a terceira pessoa a ele relacionada; II - comprovadamente, financiar, custear, patrocinar ou de qualquer modo subvencionar a prática dos atos ilícitos previstos nesta Lei; III - utilizar-se de interposta pessoa física ou jurídica para ocultar ou dissimular seus reais interesses ou a identidade dos beneficiários dos atos praticados; IV - no tocante a licitações e contratos: a) frustrar ou fraudar, mediante ajuste, combinação ou qualquer outro expediente, o caráter competitivo de procedimento licitatório público; b) impedir, perturbar ou fraudar a realização de qualquer ato de procedimento licitatório público; c) afastar ou procurar afastar licitante, por meio de fraude ou oferecimento de vantagem de qualquer tipo; d) fraudar licitação pública ou contrato dela decorrente; e) criar, de modo fraudulento ou irregular, pessoa jurídica para participar de licitação pública ou celebrar contrato administrativo; f) obter vantagem ou benefício indevido, de modo fraudulento, de modificações ou prorrogações de contratos celebrados com a administração pública; g) manipular ou fraudar o equilíbrio econômico-financeiro dos contratos celebrados com a administração pública; V - dificultar atividade de investigação ou fiscalização de órgãos, entidades ou agentes públicos.', '2013-08-01', 14, 492),
('Lei nº 12.846/2013 — art. 6º', 'Na esfera administrativa, serão aplicadas às pessoas jurídicas consideradas responsáveis pelos atos lesivos previstos nesta Lei as seguintes sanções: I - multa, no valor de 0,1% (um décimo por cento) a 20% (vinte por cento) do faturamento bruto do último exercício anterior ao da instauração do processo administrativo, excluídos os tributos, a qual nunca será inferior à vantagem auferida, quando for possível sua estimação; e II - publicação extraordinária da decisão condenatória. § 4º Na hipótese do inciso I do caput, caso não seja possível utilizar o critério do valor do faturamento bruto da pessoa jurídica, a multa será de R$ 6.000,00 (seis mil reais) a R$ 60.000.000,00 (sessenta milhões de reais).', '2013-08-01', 14, 492),
('Lei nº 12.846/2013 — art. 16 (caput)', 'A autoridade máxima de cada órgão ou entidade pública poderá celebrar acordo de leniência com as pessoas jurídicas responsáveis pela prática dos atos previstos nesta Lei que colaborem efetivamente com as investigações e o processo administrativo, sendo que dessa colaboração resulte: I - a identificação dos demais envolvidos na infração, quando couber; e II - a obtenção célere de informações e documentos que comprovem o ilícito sob apuração. § 1º O acordo de que trata o caput somente poderá ser celebrado se preenchidos cumulativamente os seguintes requisitos: I - a pessoa jurídica seja a primeira a se manifestar sobre seu interesse em cooperar; II - a pessoa jurídica cesse completamente seu envolvimento na infração; III - a pessoa jurídica admita sua participação no ilícito e coopere plena e permanentemente.', '2013-08-01', 14, 492),

-- -----------------------------------------------------------------------------
-- DIREITO ADMINISTRATIVO (ID 14) — TÓPICO 495: Lei de Acesso à Informação (Lei nº 12.527/2011)
-- -----------------------------------------------------------------------------
('Lei nº 12.527/2011 — art. 3º', 'Os procedimentos previstos nesta Lei destinam-se a assegurar o direito fundamental de acesso à informação e devem ser executados em conformidade com os princípios básicos da administração pública e com as seguintes diretrizes: I - observância da publicidade como preceito geral e do sigilo como exceção; II - divulgação de informações de interesse público, independentemente de solicitações; III - utilização de meios de comunicação viabilizados pela tecnologia da informação; IV - fomento ao desenvolvimento da cultura de transparência na administração pública; V - desenvolvimento do controle social da administração pública.', '2011-11-18', 14, 495),
('Lei nº 12.527/2011 — art. 10', 'Qualquer interessado poderá apresentar pedido de acesso a informações aos órgãos e entidades referidos no art. 1º desta Lei, por qualquer meio legítimo, devendo o pedido conter a identificação do requerente e a especificação da informação demandada. § 3º São vedadas quaisquer exigências relativas aos motivos determinantes da solicitação de informações de interesse público.', '2011-11-18', 14, 495),
('Lei nº 12.527/2011 — art. 11', 'O órgão ou entidade pública deverá autorizar ou conceder o acesso imediato à informação disponível. § 1º Não sendo possível conceder o acesso imediato, na forma disposta no caput, o órgão ou entidade que receber o pedido deverá, em prazo não superior a 20 (vinte) dias: I - comunicar a data, local e modo para se realizar a consulta, efetuar a reprodução ou obter a certidão; II - indicar as razões de fato ou de direito da recusa, total ou parcial, do acesso pretendido; ou III - comunicar que não possui a informação, indicar, se for do seu conhecimento, o órgão ou a entidade que a detém, ou, ainda, remeter o requerimento a esse órgão ou entidade, cientificando o interessado da remessa de seu pedido de informação. § 2º O prazo referido no § 1º poderá ser prorrogado por mais 10 (dez) dias, mediante justificativa expressa, da qual será cientificado o requerente.', '2011-11-18', 14, 495),
('Lei nº 12.527/2011 — art. 24', 'A informação em poder dos órgãos e entidades públicas, observado o seu teor e em razão de sua imprescindibilidade à segurança da sociedade ou do Estado, poderá ser classificada como ultrassecreta, secreta ou reservada. § 1º Os prazos máximos de restrição de acesso à informação, conforme a classificação prevista no caput, vigoram a partir da data de sua produção e são os seguintes: I - ultrassecreta: 25 (vinte e cinco) anos; II - secreta: 15 (quinze) anos; e III - reservada: 5 (cinco) anos.', '2011-11-18', 14, 495),

-- -----------------------------------------------------------------------------
-- DIREITO ADMINISTRATIVO (ID 14) — TÓPICO 496: LGPD (Lei nº 13.709/2018)
-- -----------------------------------------------------------------------------
('Lei nº 13.709/2018 — art. 6º', 'As atividades de tratamento de dados pessoais deverão observar a boa-fé e os seguintes princípios: I - finalidade: realização do tratamento para propósitos legítimos, específicos, explícitos e informados ao titular; II - adequação: compatibilidade do tratamento com as finalidades informadas ao titular; III - necessidade: limitação do tratamento ao mínimo necessário para a realização de suas finalidades; IV - livre acesso: garantia, aos titulares, de consulta facilitada e gratuita sobre a forma e a duração do tratamento; V - qualidade dos dados: exatidão, clareza, relevância e atualização dos dados; VI - transparência: informações claras, precisas e facilmente acessíveis; VII - segurança: utilização de medidas técnicas e administrativas aptas a proteger os dados; VIII - prevenção: adoção de medidas para prevenir a ocorrência de danos; IX - não discriminação: impossibilidade de realização do tratamento para fins discriminatórios ilícitos ou abusivos; X - responsabilização e prestação de contas: demonstração da adoção de medidas eficazes e capazes de comprovar a observância e o cumprimento das normas.', '2018-08-14', 14, 496),
('Lei nº 13.709/2018 — art. 7º', 'O tratamento de dados pessoais somente poderá ser realizado nas seguintes hipóteses: I - mediante o fornecimento de consentimento pelo titular; II - para o cumprimento de obrigação legal ou regulatória pelo controlador; III - pela administração pública, para o tratamento e uso compartilhado de dados necessários à execução de políticas públicas; IV - para a realização de estudos por órgão de pesquisa, garantida, sempre que possível, a anonimização; V - quando necessário para a execução de contrato ou de procedimentos preliminares relacionados a contrato do qual seja parte o titular; VI - para o exercício regular de direitos em processo judicial, administrativo ou arbitral; VII - para a proteção da vida ou da incolumidade física do titular ou de terceiro; VIII - para a tutela da saúde, exclusivamente, em procedimento realizado por profissionais de saúde, serviços de saúde ou autoridade sanitária; IX - quando necessário para atender aos interesses legítimos do controlador ou de terceiro; X - para a proteção do crédito.', '2018-08-14', 14, 496),
('Lei nº 13.709/2018 — art. 11 (caput)', 'O tratamento de dados pessoais sensíveis somente poderá ocorrer nas seguintes hipóteses: I - quando o titular ou seu responsável legal consentir, de forma específica e destacada, para finalidades específicas; II - sem fornecimento de consentimento do titular, nas hipóteses em que for indispensável para: a) cumprimento de obrigação legal ou regulatória pelo controlador; b) tratamento compartilhado de dados necessários à execução, pela administração pública, de políticas públicas; c) realização de estudos por órgão de pesquisa; d) exercício regular de direitos, inclusive em contrato e em processo judicial, administrativo e arbitral; e) proteção da vida ou da incolumidade física do titular ou de terceiro; f) tutela da saúde, exclusivamente, em procedimento realizado por profissionais de saúde; g) garantia da prevenção à fraude e à segurança do titular.', '2018-08-14', 14, 496),
('Lei nº 13.709/2018 — art. 18', 'O titular dos dados pessoais tem direito a obter do controlador, em relação aos dados do titular por ele tratados, a qualquer momento e mediante requisição: I - confirmação da existência de tratamento; II - acesso aos dados; III - correção de dados incompletos, inexatos ou desatualizados; IV - anonimização, bloqueio ou eliminação de dados desnecessários, excessivos ou tratados em desconformidade com o disposto nesta Lei; V - portabilidade dos dados a outro fornecedor de serviço ou produto; VI - eliminação dos dados pessoais tratados com o consentimento do titular; VII - informação das entidades públicas e privadas com as quais o controlador realizou uso compartilhado de dados; VIII - informação sobre a possibilidade de não fornecer consentimento e sobre as consequências da negativa; IX - revogação do consentimento.', '2018-08-14', 14, 496),

-- -----------------------------------------------------------------------------
-- DIREITO PENAL (ID 12) — TÓPICO 72: Concurso de Pessoas (CP)
-- -----------------------------------------------------------------------------
('CP — art. 29 (caput)', 'Quem, de qualquer modo, concorre para o crime incide nas penas a este cominadas, na medida de sua culpabilidade. § 1º Se a participação for de menor importância, a pena pode ser diminuída de um sexto a um terço. § 2º Se algum dos concorrentes quis participar de crime menos grave, ser-lhe-á aplicada a pena deste; essa pena será aumentada até metade, na hipótese de ter sido previsível o resultado mais grave.', '1984-07-11', 12, 72),
('CP — art. 30', 'Não se comunicam as circunstâncias e as condições de caráter pessoal, salvo quando elementares do crime.', '1984-07-11', 12, 72),
('CP — art. 31', 'O ajuste, a determinação ou instigação e o auxílio, salvo disposição expressa em contrário, não são puníveis, se o crime não chega, pelo menos, a ser tentado.', '1984-07-11', 12, 72),

-- -----------------------------------------------------------------------------
-- DIREITO PENAL (ID 12) — TÓPICO 123: Concurso de Crimes (CP)
-- -----------------------------------------------------------------------------
('CP — art. 69 (caput)', 'Quando o agente, mediante mais de uma ação ou omissão, pratica dois ou mais crimes, idênticos ou não, aplicam-se cumulativamente as penas privativas de liberdade em que haja incorrido (concurso material). No caso de aplicação cumulativa de penas de reclusão e de detenção, executa-se primeiro aquela.', '1984-07-11', 12, 123),
('CP — art. 70 (caput)', 'Quando o agente, mediante uma só ação ou omissão, pratica dois ou mais crimes, idênticos ou não, aplica-se-lhe a mais grave das penas cabíveis ou, se iguais, somente uma delas, mas aumentada, em qualquer caso, de um sexto até metade (concurso formal). As penas aplicam-se, entretanto, cumulativamente, se a ação ou omissão é dolosa e os crimes concorrentes resultam de desígnios autônomos (concurso formal impróprio).', '1984-07-11', 12, 123),
('CP — art. 71 (caput)', 'Quando o agente, mediante mais de uma ação ou omissão, pratica dois ou mais crimes da mesma espécie e, pelas condições de tempo, lugar, maneira de execução e outras semelhantes, devem os subseqüentes ser havidos como continuação do primeiro, aplica-se-lhe a pena de um só dos crimes, se idênticas, ou a mais grave, se diversas, aumentada, em qualquer caso, de um sexto a dois terços (crime continuado).', '1984-07-11', 12, 123),

-- -----------------------------------------------------------------------------
-- DIREITO PENAL (ID 12) — TÓPICO 73: Punibilidade e Prescrição (CP)
-- -----------------------------------------------------------------------------
('CP — art. 107', 'Extingue-se a punibilidade: I - pela morte do agente; II - pela anistia, graça ou indulto; III - pela retroatividade de lei que não mais considera o fato como criminoso; IV - pela prescrição, decadência ou perempção; V - pela renúncia do direito de queixa ou pelo perdão aceito, nos crimes de ação privada; VI - pela retratação do agente, nos casos em que a lei a admite; IX - pelo perdão judicial, nos casos previstos em lei.', '1984-07-11', 12, 73),
('CP — art. 109', 'A prescrição, antes de transitar em julgado a sentença final, salvo o disposto no § 1o do art. 110 deste Código, regula-se pelo máximo da pena privativa de liberdade cominada ao crime, verificando-se: I - em vinte anos, se o máximo da pena é superior a doze; II - em dezesseis anos, se o máximo da pena é superior a oito anos e não excede a doze; III - em doze anos, se o máximo da pena é superior a quatro anos e não excede a oito; IV - em oito anos, se o máximo da pena é superior a dois anos e não excede a quatro; V - em quatro anos, se o máximo da pena é igual a um ano ou, sendo superior, não excede a dois; VI - em 3 (três) anos, se o máximo da pena é inferior a 1 (um) ano.', '2010-05-05', 12, 73),
('CP — art. 115', 'São reduzidos de metade os prazos de prescrição quando o criminoso era, ao tempo do crime, menor de 21 (vinte e um) anos, ou, na data da sentença, maior de 70 (setenta) anos.', '1984-07-11', 12, 73),

-- -----------------------------------------------------------------------------
-- DIREITO PENAL (ID 12) — TÓPICO 198: Crimes Contra a Fé Pública (CP)
-- -----------------------------------------------------------------------------
('CP — art. 297 (caput)', 'Falsificar, no todo ou em parte, documento público, ou alterar documento público verdadeiro: Pena - reclusão, de dois a seis anos, e multa. § 1º Se o agente é funcionário público, e comete o crime prevalecendo-se do cargo, aumenta-se a pena de sexta parte. § 2º Para os efeitos penais, equiparam-se a documento público o emanado de entidade paraestatal, o título ao portador ou transmissível por endosso, as ações de sociedade comercial, os livros mercantis e o testamento particular.', '1940-12-07', 12, 198),
('CP — art. 298 (caput)', 'Falsificar, no todo ou em parte, documento particular ou alterar documento particular verdadeiro: Pena - reclusão, de um a cinco anos, e multa. Parágrafo único. Para fins do disposto no caput, equipara-se a documento particular o cartão de crédito ou débito.', '1940-12-07', 12, 198),
('CP — art. 299 (caput)', 'Omitir, em documento público ou particular, declaração que dele devia constar, ou nele inserir ou fazer inserir declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre fato juridicamente relevante: Pena - reclusão, de um a cinco anos, e multa, se o documento é público, e reclusão de um a três anos, e multa, de quinhentos réis a cinco mil réis, se o documento é particular (falsidade ideológica). Parágrafo único. Se o agente é funcionário público, e comete o crime prevalecendo-se do cargo, ou se a falsificação ou alteração é de assentamento de registro civil, aumenta-se a pena de sexta parte.', '1940-12-07', 12, 198),
('CP — art. 304', 'Fazer uso de qualquer dos papéis falsificados ou alterados, a que se referem os arts. 297 a 302: Pena - a cominada à falsificação ou à alteração.', '1940-12-07', 12, 198),

-- -----------------------------------------------------------------------------
-- DIREITO PENAL (ID 12) — TÓPICO 203: Crimes Contra a Dignidade Sexual (CP)
-- -----------------------------------------------------------------------------
('CP — art. 213 (caput)', 'Constranger alguém, mediante violência ou grave ameaça, a ter conjunção carnal ou a praticar ou permitir que com ele se pratique outro ato libidinoso: Pena - reclusão, de 6 a 10 anos.', '2009-08-07', 12, 203),
('CP — art. 215-A (caput)', 'Praticar contra alguém e sem a sua anuência ato libidinoso com o objetivo de satisfazer a própria lascívia ou a de terceiro: Pena - reclusão, de 1 (um) a 5 (cinco) anos, se o ato não constitui crime mais grave (importunação sexual).', '2018-09-24', 12, 203),
('CP — art. 217-A (caput)', 'Ter conjunção carnal ou praticar outro ato libidinoso com menor de 14 (catorze) anos: Pena - reclusão, de 8 a 15 anos (estupro de vulnerável). § 1º Incorre na mesma pena quem pratica as ações descritas no caput com alguém que, por enfermidade ou deficiência mental, não tem o necessário discernimento para a prática do ato, ou que, por qualquer outra causa, não pode oferecer resistência. § 5º As penas previstas no caput e nos §§ 1º, 3º e 4º deste artigo aplicam-se independentemente do consentimento da vítima ou do fato de ela já ter mantido relações sexuais anteriormente.', '2009-08-07', 12, 203),

-- -----------------------------------------------------------------------------
-- DIREITO PROCESSUAL PENAL (ID 13) — TÓPICO 288: Ação Penal (CPP)
-- -----------------------------------------------------------------------------
('CPP — art. 24 (caput)', 'Nos crimes de ação pública, esta será promovida por denúncia do Ministério Público, mas dependerá, quando a lei o exigir, de requisição do Ministro da Justiça, ou de representação do ofendido ou de quem tiver qualidade para representá-lo.', '1941-10-03', 13, 288),
('CPP — art. 28 (caput)', 'Ordenado o arquivamento do inquérito policial ou de quaisquer elementos informativos da mesma natureza, o órgão do Ministério Público comunicará à vítima, ao investigado e à autoridade policial e encaminhará os autos para a instância de revisão ministerial para fins de homologação, na forma da lei. § 1º Se a vítima, ou seu representante legal, não concordar com o arquivamento do inquérito policial, poderá, no prazo de 30 (trinta) dias do recebimento da comunicação, submeter a matéria à revisão da instância competente do órgão ministerial, conforme dispuser a respectiva lei orgânica.', '2019-12-24', 13, 288),
('CPP — art. 29', 'Será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal, cabendo ao Ministério Público aditar a queixa, repudiá-la e oferecer denúncia substitutiva, intervir em todos os termos do processo, fornecer elementos de prova, interpor recurso e, a todo tempo, no caso de negligência do querelante, retomar a ação como parte principal.', '1941-10-03', 13, 288),
('CPP — art. 38', 'Salvo disposição em contrário, o ofendido, ou seu representante legal, decairá no direito de queixa ou de representação, se não o exercer dentro do prazo de seis meses, contado do dia em que vier a saber quem é o autor do crime.', '1941-10-03', 13, 288),
('CPP — art. 41', 'A denúncia ou queixa conterá a exposição do fato criminoso, com todas as suas circunstâncias, a qualificação do acusado ou esclarecimentos pelos quais se possa identificá-lo, a classificação do crime e, quando necessário, o rol das testemunhas.', '1941-10-03', 13, 288),
('CPP — art. 42', 'O Ministério Público não poderá desistir da ação penal.', '1941-10-03', 13, 288),

-- -----------------------------------------------------------------------------
-- DIREITO PROCESSUAL PENAL (ID 13) — TÓPICO 142: Acordo de Não Persecução Penal (CPP)
-- -----------------------------------------------------------------------------
('CPP — art. 28-A (caput)', 'Não sendo caso de arquivamento e tendo o investigado confessado formal e circunstancialmente a prática de infração penal sem violência ou grave ameaça e com pena mínima inferior a 4 (quatro) anos, o Ministério Público poderá propor acordo de não persecução penal, desde que necessário e suficiente para reprovação e prevenção do crime, mediante as seguintes condições ajustadas cumulativa e alternativamente: I - reparar o dano ou restituir a coisa à vítima, exceto na impossibilidade de fazê-lo; II - renunciar voluntariamente a bens e direitos indicados pelo Ministério Público como instrumentos, produto ou proveito do crime; III - prestar serviço à comunidade ou a entidades públicas por período correspondente à pena mínima diminuída de um a dois terços; IV - pagar prestação pecuniária; V - cumprir, por prazo determinado, outra condição indicada pelo Ministério Público.', '2019-12-24', 13, 142),
('CPP — art. 28-A, § 2º', 'O disposto no caput deste artigo não se aplica: I - se for cabível transação penal de competência dos Juizados Especiais Criminais, nos termos da lei; II - se o investigado for reincidente ou se houver elementos probatórios que indiquem conduta criminal habitual, reiterada ou profissional, salvo se insignificantes as infrações pretéritas; III - ter sido o agente beneficiado nos 5 (cinco) anos anteriores ao cometimento da infração em acordo de não persecução penal, transação penal ou suspensão condicional do processo; e IV - nos crimes praticados no âmbito de violência doméstica ou familiar, ou praticados contra a mulher por razões da condição do sexo feminino, em favor do agressor.', '2019-12-24', 13, 142),

-- -----------------------------------------------------------------------------
-- DIREITO PROCESSUAL PENAL (ID 13) — TÓPICO 141: Juizados Especiais Criminais (Lei nº 9.099/1995)
-- -----------------------------------------------------------------------------
('Lei nº 9.099/1995 — art. 60', 'O Juizado Especial Criminal, provido por juízes togados ou togados e leigos, tem competência para a conciliação, o julgamento e a execução das infrações penais de menor potencial ofensivo, respeitadas as regras de conexão e continência.', '1995-09-26', 13, 141),
('Lei nº 9.099/1995 — art. 61', 'Consideram-se infrações penais de menor potencial ofensivo, para os efeitos desta Lei, as contravenções penais e os crimes a que a lei comine pena máxima não superior a 2 (dois) anos, cumulada ou não com multa.', '2006-06-28', 13, 141),
('Lei nº 9.099/1995 — art. 74', 'A composição dos danos civis será reduzida a escrito e, homologada pelo Juiz mediante sentença irrecorrível, terá eficácia de título a ser executado no juízo civil competente. Parágrafo único. Tratando-se de ação penal de iniciativa privada ou de ação penal pública condicionada à representação, o acordo homologado acarreta a renúncia ao direito de queixa ou à representação.', '1995-09-26', 13, 141),
('Lei nº 9.099/1995 — art. 76 (caput)', 'Havendo representação ou tratando-se de crime de ação penal pública incondicionada, não sendo caso de arquivamento, o Ministério Público poderá propor a aplicação imediata de pena restritiva de direitos ou multas, a ser especificada na proposta (transação penal). § 2º Não se admitirá a proposta se ficar comprovado: I - ter sido o autor da infração condenado, pela prática de crime, à pena privativa de liberdade, por sentença definitiva; II - ter sido o agente beneficiado anteriormente, no prazo de cinco anos, pela aplicação de pena restritiva ou multa; III - não indicarem os antecedentes, a conduta social e a personalidade do agente, bem como os motivos e as circunstâncias, ser necessária e suficiente a adoção da medida.', '1995-09-26', 13, 141),

-- -----------------------------------------------------------------------------
-- DIREITO PROCESSUAL PENAL (ID 13) — TÓPICO 79: Prisão Temporária (Lei nº 7.960/1989)
-- -----------------------------------------------------------------------------
('Lei nº 7.960/1989 — art. 1º', 'Caberá prisão temporária: I - quando imprescindível para as investigações do inquérito policial; II - quando o indicado não tiver residência fixa ou não fornecer elementos necessários ao esclarecimento de sua identidade; III - quando houver fundadas razões, de acordo com qualquer prova admitida na legislação penal, de autoria ou participação do indiciado nos seguintes crimes: homicídio doloso, sequestro, roubo, extorsão, estupro, epidemia com resultado de morte, envenenamento de água potável ou substância alimentícia ou medicinal, quadrilha ou bando, genocídio, tráfico de drogas e crimes contra o sistema financeiro.', '1989-12-21', 13, 79),
('Lei nº 7.960/1989 — art. 2º (caput)', 'A prisão temporária será decretada pelo Juiz, em face da representação da autoridade policial ou de requerimento do Ministério Público, e terá o prazo de 5 (cinco) dias, prorrogável por igual período em caso de extrema e comprovada necessidade.', '1989-12-21', 13, 79),

-- -----------------------------------------------------------------------------
-- DIREITO PROCESSUAL PENAL (ID 13) — TÓPICO 173: Interceptação Telefônica (Lei nº 9.296/1996)
-- -----------------------------------------------------------------------------
('Lei nº 9.296/1996 — art. 1º', 'A interceptação de comunicações telefônicas, de qualquer natureza, para prova em investigação criminal e em instrução processual penal, observará o disposto nesta Lei e dependerá de ordem do juiz competente da ação principal, sob segredo de justiça.', '1996-07-24', 13, 173),
('Lei nº 9.296/1996 — art. 2º', 'Não será admitida a interceptação de comunicações telefônicas quando ocorrer qualquer das seguintes hipóteses: I - não houver indícios razoáveis da autoria ou participação em infração penal; II - a prova puder ser feita por outros meios disponíveis; III - o fato investigado constituir infração penal punida, no máximo, com pena de detenção.', '1996-07-24', 13, 173),
('Lei nº 9.296/1996 — art. 5º', 'A decisão será fundamentada, sob pena de nulidade, indicando também a forma de execução da medida, que não poderá exceder o prazo de quinze dias, renovável por igual tempo uma vez comprovada a indispensabilidade do meio de prova.', '1996-07-24', 13, 173)

on conflict (referencia) do update set 
    texto = excluded.texto, 
    vigencia_de = excluded.vigencia_de, 
    id_materia = excluded.id_materia, 
    id_topico = excluded.id_topico;
